# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.models import Span
from hourglass.gaps import find_gaps

HOURS = parse_span("08:00-18:00")


def spans(*texts):
    return [parse_span(text) for text in texts]


def gaps_for(*texts):
    return find_gaps(spans(*texts), HOURS)


class FindGapsTests(unittest.TestCase):
    def test_gap_in_the_middle(self):
        labels = gaps_for("08:00-12:00", "13:00-18:00")
        want = ["gap 12:00-13:00 (60 min)"]
        self.assertEqual(labels, want)

    def test_gaps_at_both_ends(self):
        labels = gaps_for("09:00-17:00")
        self.assertEqual(labels, [
            "gap 08:00-09:00 (60 min)",
            "gap 17:00-18:00 (60 min)"
        ])

    def test_overlaps_and_order_do_not_matter(self):
        labels = gaps_for(
            "13:00-18:00", "08:00-12:30", "09:00-12:00"
        )
        want = ["gap 12:30-13:00 (30 min)"]
        self.assertEqual(labels, want)

    def test_full_coverage_has_no_gaps(self):
        labels = gaps_for("08:00-13:00", "13:00-18:00")
        self.assertEqual(labels, [])

    def test_nobody_working_is_one_big_gap(self):
        labels = gaps_for()
        want = ["gap 08:00-18:00 (600 min)"]
        self.assertEqual(labels, want)

    def test_span_outside_hours_raises(self):
        for text in ("07:00-09:00", "17:00-19:00"):
            with self.assertRaises(ValueError):
                gaps_for(text)

    def test_accepts_any_iterable(self):
        worked = iter([Span(480, 1080)])
        self.assertEqual(find_gaps(worked, HOURS), [])
